function act(type){
 if(mode!=='battle'||battle.busy)return;
 const hero=party[0], wild=battle.wild;
 if(type==='run'){if(Math.random()<.88){mode='world';battle=null;toast='You slipped away safely. The grass is still rustling…';toastTimer=3;}else{battle.message='The wild meme-mon blocks the path!';enemyTurn();}return;}
 if(type==='capture'){
   if(battle.capsules<=0){battle.message='No more espresso capsules! Try a little damage first.';return;}
   battle.capsules--;battle.message='You toss an Espresso Capsule…';battle.busy=true;
   setTimeout(()=>{
     let chance=clamp(.24+(1-wild.hp/wild.maxHp)*.63,.24,.89);
     if(Math.random()<chance){
       if(party.length<6){party.push({id:wild.id,name:wild.name,level:wild.level,hp:wild.maxHp,maxHp:wild.maxHp,xp:0});caught++;battle.message=`Gotcha! ${wild.name} joined your crew!`;}
       else{caught++;battle.message=`Gotcha! ${wild.name} is safe in your reserve!`;}
       battle.busy=false;setTimeout(()=>{if(mode==='battle'){mode='world';battle=null;toast='New friend acquired! Check your crew.';toastTimer=3.5;}},1150);
     }else{battle.message=`${wild.name} popped out! Give it another go.`;battle.busy=false;enemyTurn();}
   },700);return;
 }
 battle.busy=true;
 if(type==='attack'){
   const dmg=Math.floor(rand(hero.level+4,hero.level+9));wild.hp=Math.max(0,wild.hp-dmg);battle.message=`Espresso Shot! ${wild.name} took ${dmg} damage.`;
 }else{
